const gsap=window.gsap;
export const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
export function enter(element,{y=6,duration=.2}={}){if(!element)return;gsap.killTweensOf(element);if(reducedMotion()){gsap.set(element,{clearProps:'opacity,transform,visibility'});return}gsap.fromTo(element,{opacity:0,y},{opacity:1,y:0,duration,ease:'power2.out',clearProps:'opacity,transform',overwrite:true})}
export function reveal(element,show,{onClosed}={}){gsap.killTweensOf(element);if(show){element.hidden=false;gsap.set(element,{clearProps:'pointerEvents'});if(reducedMotion())gsap.set(element,{clearProps:'opacity,transform'});else gsap.fromTo(element,{opacity:0,y:-5,scale:.985},{opacity:1,y:0,scale:1,duration:.18,ease:'power2.out',clearProps:'opacity,transform',overwrite:true})}else{const end=()=>{element.hidden=true;gsap.set(element,{clearProps:'opacity,transform,pointerEvents'});onClosed?.()};if(element.hidden||reducedMotion())end();else gsap.to(element,{opacity:0,y:-3,duration:.12,pointerEvents:'none',ease:'power1.out',onComplete:end,overwrite:true})}}
let transition=null,revision=0;
export function switchPage(commit,{animate=true}={}){const ticket=++revision;transition?.skipTransition();transition=null;const update=()=>{if(ticket!==revision)return;commit();if(!document.startViewTransition&&animate)enter(document.querySelector('.content'),{y:7,duration:.22})};if(!animate||reducedMotion()||!document.startViewTransition){update();return}const next=document.startViewTransition(update);transition=next;next.ready.catch(()=>{});next.finished.catch(()=>{}).finally(()=>{if(transition===next)transition=null})}
export function setupMotion(){const header=document.querySelector('.portal-nav');const marker=document.createElement('i');marker.className='nav-marker';marker.setAttribute('aria-hidden','true');const track=document.createElement('span');track.className='nav-marker-track';track.setAttribute('aria-hidden','true');track.append(marker);header.append(track);let frame;
 const update=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const active=header.querySelector('.nav-group > .nav.active')??header.querySelector(':scope > .nav.active');if(!active){marker.hidden=true;return}const rect=active.getBoundingClientRect(),parent=header.getBoundingClientRect();marker.hidden=false;gsap.to(marker,{x:rect.left-parent.left+header.scrollLeft,width:rect.width,duration:reducedMotion()?0:.23,ease:'power3.out',overwrite:true})})};
 new MutationObserver(update).observe(header,{subtree:true,attributes:true,attributeFilter:['class']});new ResizeObserver(update).observe(header);header.addEventListener('scroll',update,{passive:true});window.addEventListener('portal-route',update);update();
 const dialogs=new WeakMap();new MutationObserver(records=>{for(const record of records){const dialog=record.target;if(!(dialog instanceof HTMLDialogElement)||!dialog.open)continue;enter(dialog,{y:10,duration:.2});dialogs.set(dialog,true)}}).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});
}
